import test from 'node:test';
import assert from 'node:assert/strict';
import {Session, encode, decode, enablePayload, disablePayload} from '../builder/ferret.mjs';

// Golden packets generated by unmodified Ferret dd63f27, using an authored
// 00..0f challenge. No device inputs, permissions, or hardware are used here.
test('wire packets match upstream Ferret', () => {
  assert.deepEqual([...encode(9)], [240,0,32,118,33,102,32,2,33,2,9,2,24,0,247]);
  assert.deepEqual([...encode(0xac, enablePayload(Uint8Array.from({length:16}, (_, i) => i)))],
    [240,0,32,118,33,102,40,2,33,26,44,22,25,74,119,115,109,25,75,113,110,29,110,79,117,106,17,67,121,102,61,21,71,125,98,58,39,53,0,0,247]);
});

test('malformed transport cannot become a reply', () => {
  const good = encode(0x20, Uint8Array.from({length:16}, (_, i) => i));
  assert.equal(decode(good).payload.length, 16);
  for (let i = 0; i < good.length; i++) assert.equal(decode(good.slice(0,i)), null);
  const bad = good.slice(); bad[3] ^= 1; assert.equal(decode(bad), null);
  const crc = good.slice(); crc[crc.length-4] ^= 1; assert.equal(decode(crc), null);
  assert.throws(() => enablePayload(new Uint8Array(15)), /challenge/);
  assert.throws(() => enablePayload(new Uint8Array(17)), /challenge/);
});

const meta = (product = 'OP-XY', serial = 'test-unit', mode = 'te-boot') => new TextEncoder().encode(
  `product:${product};serial:${serial};bl_version:1000.0.20;mode:${mode}`);
class Port extends EventTarget {
  constructor(id, name = 'OP-XY Midi') { super(); Object.assign(this, {id,name,manufacturer:'TE',state:'connected',sent:[],closed:0}); }
  async open() {}
  async close() { this.closed++; }
  send(bytes) { this.sent.push(bytes); this.respond?.(decode(bytes)); }
}
function device(options = {}) {
  const access = new EventTarget(), input = new Port('in'), output = new Port('out');
  const other = new Port('other', 'Another synth');
  access.inputs = new Map([[input.id,input]]); access.outputs = new Map([[output.id,output],[other.id,other]]);
  const reply = (type,payload) => {
    const whole = encode(type,payload);
    let packets = [whole];
    if (options.fragmented) {
      // Transport-level split: each packet has its own 7-bit packing/header,
      // while the serial frame and CRC cross the packet boundary.
      const packed = whole.slice(6,-1), wire = [];
      for (let i=0;i<packed.length;i+=8) for(let j=1;j<8&&i+j<packed.length;j++) {
        wire.push(packed[i+j] | (((packed[i]>>(j-1))&1)<<7));
      }
      packets = [wire.slice(0,5),wire.slice(5)].map(part=>{
        const result=[240,0,32,118,33,102];
        for(let i=0;i<part.length;i+=7){const group=part.slice(i,i+7);result.push(group.reduce((n,b,j)=>n|((b>>7)<<j),0),...group.map(b=>b&127));}
        return Uint8Array.from([...result,247]);
      });
    }
    for(const packet of packets){const event=new Event('midimessage');event.data=packet;input.dispatchEvent(event);}
  };
  let metaReads = 0, requests = 0;
  output.respond = frame => {
    if (frame.type === 9) {
      metaReads++;
      queueMicrotask(() => reply(0x0a, options.metadata?.(metaReads) ?? meta()));
    }
    if (frame.type === 0x1f && !options.noChallenge) queueMicrotask(() => {
      options.beforeChallenge?.();
      reply(0x20, new Uint8Array(options.challengeLength ?? 16).fill(42));
    });
  };
  const session = new Session(async permission => {
    requests++; assert.deepEqual(permission,{sysex:true}); return access;
  }, options.disconnect, 30);
  return {session,access,input,output,other,reply,requests:()=>requests};
}
const commands = d => d.output.sent.map(bytes => decode(bytes).type);

test('serial replies spanning MIDI messages preserve Ferret stream behavior', async () => {
  const d=device({fragmented:true}); await d.session.connect(); await d.session.enable();
  assert.deepEqual(commands(d),[9,9,0x1f,0xac]); d.session.close();
});

test('no automatic access; enable requires connect and uses only the selected pair', async () => {
  const d = device(); assert.equal(d.requests(),0); assert.deepEqual(commands(d),[]);
  await assert.rejects(d.session.enable());
  await d.session.connect(); assert.deepEqual(commands(d),[9]);
  await d.session.enable(); assert.deepEqual(commands(d),[9,9,0x1f,0xac]);
  assert.equal(d.other.sent.length,0);
  assert.deepEqual([...decode(d.output.sent.at(-1)).payload], [...enablePayload(new Uint8Array(16).fill(42))]);
  d.session.close(); assert(d.input.closed && d.output.closed);
});

test('disable requires connection and changes only the bootloader marker operation', async () => {
  const d = device();
  await assert.rejects(d.session.disable());
  assert.deepEqual(commands(d), []);
  await d.session.connect();
  assert.deepEqual(commands(d), [9]);
  await d.session.disable();
  assert.deepEqual(commands(d), [9,9,0x1f,0xac]);
  const payload = decode(d.output.sent.at(-1)).payload;
  assert.deepEqual([...payload], [...disablePayload(new Uint8Array(16).fill(42))]);
  assert.deepEqual([...payload.slice(0,21)], [...enablePayload(new Uint8Array(16).fill(42)).slice(0,21)]);
  assert.equal(payload[20], 0xba); assert.equal(payload[21], 0);
  assert.equal(d.other.sent.length, 0); d.session.close();
});

test('disable rejects changed identity, malformed challenge, timeout and cancellation', async () => {
  for (const options of [
    {metadata:n=>meta('OP-XY',n===1?'first':'second')},
    {challengeLength:15}, {challengeLength:17}, {noChallenge:true},
  ]) {
    const d = device(options); await d.session.connect();
    await assert.rejects(d.session.disable());
    assert(!commands(d).includes(0xac)); d.session.close();
  }
  const d = device({beforeChallenge:()=>d.session.close()});
  await d.session.connect(); await assert.rejects(d.session.disable(), /closed/);
  assert(!commands(d).includes(0xac));
});

test('ambiguous devices and input pairs send no commands', async () => {
  for (const kind of ['outputs','inputs']) {
    const d=device(); d.access[kind].set('duplicate',new Port('duplicate'));
    await assert.rejects(d.session.connect(), /one OP|unique OP/);
    assert.deepEqual(commands(d),[]);
  }
});

test('Windows composite port names connect and diagnostics describe only reported ports', async () => {
  const d = device(), snapshots = [];
  d.input.name = d.output.name = 'OP-XY (Composite)';
  d.input.manufacturer = d.output.manufacturer = 'Teenage Engineering';
  d.input.connection = d.output.connection = 'closed';
  const session = new Session(async () => d.access, () => {}, 30, {onPorts: ports => snapshots.push(ports)});
  await session.connect();
  assert.deepEqual(commands(d), [9]);
  assert.equal(d.other.sent.length, 0);
  assert.equal(snapshots.length, 1);
  assert.deepEqual(snapshots[0].inputs, [{name:'OP-XY (Composite)', manufacturer:'Teenage Engineering', state:'connected', connection:'closed'}]);
  assert.equal(snapshots[0].outputs.length, 2);
  session.close();
});

test('missing OP-XY reports visible ports without opening or probing other devices', async () => {
  for (const empty of [false, true]) {
    const d = device(); let snapshot;
    d.access.inputs.clear(); d.access.outputs.delete(d.output.id);
    if (empty) d.access.outputs.clear();
    d.other.open = () => { throw new Error('Must not open another device'); };
    const session = new Session(async () => d.access, () => {}, 30, {onPorts: ports => { snapshot = ports; }});
    await assert.rejects(session.connect(), /no connected OP–XY MIDI output/);
    assert.deepEqual(snapshot.inputs, []);
    assert.deepEqual(snapshot.outputs.map(port => port.name), empty ? [] : ['Another synth']);
    assert.deepEqual(commands(d), []);
    assert.equal(d.other.sent.length, 0);
  }
});

test('wrong product, normal OS, changed unit, and invalid challenge never write a flag', async () => {
  for (const options of [
    {metadata:()=>meta('TX-6')}, {metadata:()=>meta('OP-XY','test-unit','normal')},
    {metadata:n=>meta('OP-XY',n===1?'first':'second')}, {challengeLength:15}, {challengeLength:17}
  ]) {
    const d=device(options);
    await assert.rejects(async()=>{await d.session.connect();await d.session.enable();});
    assert(!commands(d).includes(0xac)); d.session.close();
  }
});

test('challenge timeout disconnects and prevents retries from writing', async () => {
  const d=device({noChallenge:true}); await d.session.connect();
  await assert.rejects(d.session.enable(), /No reply/);
  await assert.rejects(d.session.enable(), /disconnected/);
  assert(!commands(d).includes(0xac));
});

test('disconnect during challenge aborts without writing or switching ports', async () => {
  let disconnected = 0, d;
  d=device({disconnect:()=>disconnected++,beforeChallenge:()=>{
    d.output.state='disconnected'; d.access.dispatchEvent(new Event('statechange'));
  }});
  await d.session.connect(); await assert.rejects(d.session.enable(), /closed/);
  assert.equal(disconnected,1); assert(!commands(d).includes(0xac)); assert.equal(d.other.sent.length,0);
});

test('double action and cancellation while awaiting permission cannot write', async () => {
  let grant;
  const d=device(); const session=new Session(()=>new Promise(r=>grant=r));
  const connection=session.connect();
  await assert.rejects(session.enable(), /current step/);
  session.close(); grant(d.access);
  await assert.rejects(connection, /cancelled/);
  assert.deepEqual(commands(d),[]);
});

test('denied permission does not open ports or transmit', async () => {
  const session=new Session(async()=>{throw new Error('Permission denied');});
  await assert.rejects(session.connect(), /Permission denied/);
  await assert.rejects(session.enable(), /disconnected/);
});

test('MIDI initialization timeout releases the session and ignores a late grant', async () => {
  let grant; const d=device(), phases=[];
  const session=new Session(()=>new Promise(r=>grant=r),()=>{},30,
    {accessTimeout:20,onProgress:phase=>phases.push(phase)});
  await assert.rejects(session.connect(), /initializing MIDI/);
  grant(d.access); await new Promise(r=>setTimeout(r,0));
  assert.deepEqual(commands(d),[]); assert.match(phases[0],/Chrome MIDI access/);
  session.requestAccess=async()=>d.access;
  await session.connect(); assert.deepEqual(commands(d),[9]); session.close();
});

test('cancel works while MIDI access never settles and allows a retry', async () => {
  const d=device();const session=new Session(()=>new Promise(()=>{}));
  const connection=session.connect(); session.close();
  await assert.rejects(connection,/cancelled/);
  session.requestAccess=async()=>d.access;
  await session.connect(); assert.deepEqual(commands(d),[9]);session.close();
});

test('both port-open waits time out without sending metadata or a flag', async () => {
  for(const which of ['input','output']) {
    const d=device();let opened;
    d[which].open=()=>new Promise(resolve=>opened=resolve);
    const session=new Session(async()=>d.access,()=>{},30,{portTimeout:20});
    await assert.rejects(session.connect(),/could not open/);
    opened();await new Promise(r=>setTimeout(r,0));
    assert.deepEqual(commands(d),[]);assert(d[which].closed>=1);
  }
});
